using System;using System.Linq;using System.IO;using System.Text;using System.Security.Cryptography;using CodexLight.Bootstrap;
class Program{
 static int count;static void Check(bool x){if(!x)throw new Exception("assertion failed");count++;}static void Reject(Action fn){try{fn();}catch(InvalidOperationException){count++;return;}throw new Exception("expected rejection");}
 static UpgradeFile F(string p,string h="a")=>new UpgradeFile(p,1,string.Concat(Enumerable.Repeat(h,64)));
 sealed class Registry:IUpgradeRegistration{public string Value="old-registration";public bool Fail;public string Read()=>Value;public void Write(string value){if(Fail&&value!="old-registration")throw new IOException("injected registry failure");Value=value;}}
 static UpgradeFile FileData(string path,string data){using(var h=SHA256.Create())return new UpgradeFile(path,Encoding.UTF8.GetByteCount(data),BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(data))).Replace("-","").ToLowerInvariant());}
 static void TransactionTests(){
  foreach(string fault in new[]{"none","intent-0","backup-0","install-0","applied-0","files-verified","registration-written","registry","modified-target"}){
   string temp=Path.Combine(Path.GetTempPath(),"codex-upgrade-test-"+Guid.NewGuid().ToString("N")),root=Path.Combine(temp,"app"),source=Path.Combine(temp,"source");Directory.CreateDirectory(root);Directory.CreateDirectory(source);
   try{File.WriteAllText(Path.Combine(root,"CodexLight.exe"),"old");File.WriteAllText(Path.Combine(root,"user.txt"),"user data");File.WriteAllText(Path.Combine(source,"CodexLight.exe"),"new");File.WriteAllText(Path.Combine(source,"new.dll"),"add");
    var old=new[]{FileData("CodexLight.exe","old")};var receipt=new InstallReceipt(Guid.NewGuid().ToString("D"),@"C:\Users\USER\Apps\codexlight",old);var next=new[]{FileData("CodexLight.exe","new"),FileData("new.dll","add")};var plan=UpgradePlanner.Create(receipt,receipt.Target,"\""+receipt.Target+"\\Uninstall.exe\" /uninstall",receipt.Fingerprint(),next,old.Concat(new[]{FileData("user.txt","user data")}),false);var registry=new Registry{Fail=fault=="registry"};
    var transaction=new UpgradeTransaction(root,source,plan,registry,()=>false,name=>{if(fault=="modified-target"&&name=="install-0"){File.WriteAllText(Path.Combine(root,"CodexLight.exe"),"user modified");throw new IOException("injected external edit");}if(name==fault)throw new IOException("injected failure");});
    if(fault=="modified-target"){Reject(()=>transaction.Execute(true,"new-registration"));Check(File.ReadAllText(Path.Combine(root,"CodexLight.exe"))=="user modified");Reject(()=>transaction.Recover(true));}
    else if(fault=="none"){transaction.Execute(true,"new-registration");Check(File.ReadAllText(Path.Combine(root,"CodexLight.exe"))=="new");Check(registry.Value=="new-registration");Check(transaction.Recover(true)=="committed");}
    else{try{transaction.Execute(true,"new-registration");throw new Exception("expected injected failure");}catch(IOException){}Check(File.ReadAllText(Path.Combine(root,"CodexLight.exe"))=="old");Check(!File.Exists(Path.Combine(root,"new.dll")));Check(registry.Value=="old-registration");Check(transaction.Recover(true)=="rolled-back");}
    Check(File.ReadAllText(Path.Combine(root,"user.txt"))=="user data");Check(!File.Exists(Path.Combine(root,"CodexLight.upgrade.lock")));
    // Unknown fields/noncanonical bytes cannot be accepted as a recovery journal.
    File.AppendAllText(Path.Combine(root,"CodexLight.upgrade-journal.json")," ");Reject(()=>transaction.Recover(true));
   }finally{Directory.Delete(temp,true);}
  }
 }
 sealed class Lease:IDisposable{readonly Action release;public Lease(Action release){this.release=release;}public void Dispose()=>release();}
 static void OrchestratorTests(){string temp=Path.Combine(Path.GetTempPath(),"codex-orchestrator-"+Guid.NewGuid().ToString("N")),root=Path.Combine(temp,"app"),source=Path.Combine(temp,"source");Directory.CreateDirectory(root);Directory.CreateDirectory(source);try{
  string identity=@"C:\Users\USER\Apps\codexlight";var old=new InstallReceipt(Guid.NewGuid().ToString("D"),identity,new[]{FileData("CodexLight.exe","old")});var codec=new WindowsUpgradeRegistration(identity);var registry=new Registry{Value=codec.Next(old)};File.WriteAllText(Path.Combine(root,"CodexLight.exe"),"old");File.WriteAllText(Path.Combine(root,"mine.txt"),"mine");File.WriteAllBytes(Path.Combine(root,UpgradeReceiptCodec.Filename),UpgradeReceiptCodec.Encode(old));File.WriteAllText(Path.Combine(source,"CodexLight.exe"),"new");bool held=false,running=false;
  Func<IDisposable> acquire=()=>{if(held)throw new InvalidOperationException("mutex busy");held=true;return new Lease(()=>held=false);};var service=new UpgradeOrchestrator(root,identity,source,new[]{FileData("CodexLight.exe","new")},registry,acquire,()=>running);
  held=true;Reject(()=>service.Preview());held=false;running=true;Reject(()=>service.Preview());running=false;
  using(var huge=new FileStream(Path.Combine(root,"CodexLight.exe"),FileMode.Open)){huge.SetLength(2L*1024*1024*1024);}Reject(()=>service.Preview());File.WriteAllText(Path.Combine(root,"CodexLight.exe"),"old");var preview=service.Preview();Check(preview.Plan.PreservedUnknown.Contains("mine.txt"));Reject(()=>service.Apply(preview,false));Check(File.ReadAllText(Path.Combine(root,"CodexLight.exe"))=="old");service.Apply(preview,true);Check(!held);Check(File.ReadAllText(Path.Combine(root,"CodexLight.exe"))=="new");Check(File.ReadAllText(Path.Combine(root,"mine.txt"))=="mine");Check(!File.Exists(Path.Combine(root,"CodexLight.upgrade-context.json")));Check(!File.Exists(Path.Combine(root,"CodexLight.upgrade-journal.json")));var record=codec.Parse(registry.Read());Check(UpgradeReceiptCodec.Decode(File.ReadAllBytes(Path.Combine(root,UpgradeReceiptCodec.Filename)),record.ReceiptHash,identity).InstallId==old.InstallId);Check(Directory.GetDirectories(root,"CodexLight.upgrade-*").Length==1);
  // Synthetic repair uses a reviewed-evidence callback; no body file changed or unknown removed.
  File.Delete(Path.Combine(root,UpgradeReceiptCodec.Filename));registry.Value="{\"Exists\":false,\"InstallLocation\":\"\",\"UninstallString\":\"\",\"InstallId\":\"\",\"ReceiptHash\":\"\"}";var repairedReceipt=new InstallReceipt(Guid.NewGuid().ToString("D"),identity,new[]{FileData("CodexLight.exe","new")});var repair=new UpgradeOrchestrator(root,identity,source,new[]{FileData("CodexLight.exe","new")},registry,acquire,()=>false,(target,confirmed)=>{Check(target==root&&confirmed);return repairedReceipt;});Reject(()=>repair.RepairLegacy(false));repair.RepairLegacy(true);Check(File.ReadAllText(Path.Combine(root,"CodexLight.exe"))=="new");Check(File.ReadAllText(Path.Combine(root,"mine.txt"))=="mine");Check(codec.Parse(registry.Read()).ReceiptHash==repairedReceipt.Fingerprint());
  File.WriteAllText(Path.Combine(source,"CodexLight.exe"),"third");var failedService=new UpgradeOrchestrator(root,identity,source,new[]{FileData("CodexLight.exe","third")},registry,acquire,()=>false);var failedPreview=failedService.Preview();registry.Fail=true;try{failedService.Apply(failedPreview,true);throw new Exception("expected registry failure");}catch(IOException){}registry.Fail=false;Check(File.ReadAllText(Path.Combine(root,"CodexLight.exe"))=="new");Check(File.Exists(Path.Combine(root,"CodexLight.upgrade-context.json")));File.WriteAllText(Path.Combine(root,"CodexLight.upgrade.lock"),"");Reject(()=>failedService.Recover(true,false));Check(File.Exists(Path.Combine(root,"CodexLight.upgrade.lock")));Check(failedService.Recover(true,true)=="rolled-back");Check(!File.Exists(Path.Combine(root,"CodexLight.upgrade-context.json")));Check(!File.Exists(Path.Combine(root,"CodexLight.upgrade.lock")));Check(File.ReadAllText(Path.Combine(root,"mine.txt"))=="mine");

 }finally{Directory.Delete(temp,true);}}
 sealed class GrowingStream:MemoryStream{public GrowingStream(byte[] bytes):base(bytes){}public override long Length=>0;}
 static void BoundedTests(){using(var input=new MemoryStream(new byte[10])){Reject(()=>BoundedFile.Read(input,4));Check(input.Position==5);}using(var growing=new GrowingStream(new byte[20])){Reject(()=>BoundedFile.Read(growing,3));Check(growing.Position==4);}using(var growing=new GrowingStream(new byte[20])){Reject(()=>BoundedFile.Hash(growing,3));Check(growing.Position==4);}using(var shortStream=new MemoryStream(new byte[2]))Reject(()=>BoundedFile.Hash(shortStream,3));using(var exact=new MemoryStream(new byte[4]))Check(BoundedFile.Read(exact,4).Length==4);
 string temp=Path.Combine(Path.GetTempPath(),"codex-bound-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(temp);try{string huge=Path.Combine(temp,"metadata.json");using(var file=new FileStream(huge,FileMode.CreateNew)){file.SetLength(2L*1024*1024*1024);}Reject(()=>BoundedFile.Read(huge,16));Reject(()=>BoundedFile.Hash(huge,3));Reject(()=>BoundedFile.Copy(huge,Path.Combine(temp,"copy"),3));Check(!File.Exists(Path.Combine(temp,"copy")));File.WriteAllText(Path.Combine(temp,"small"),"abc");BoundedFile.CopyMetadata(Path.Combine(temp,"small"),Path.Combine(temp,"copied"),3);Check(File.ReadAllText(Path.Combine(temp,"copied"))=="abc");}finally{Directory.Delete(temp,true);}
 }
 static void Main(){Check(CodexLight.Shared.InstallMaintenance.Key(Path.GetTempPath(),"SID-A")==CodexLight.Shared.InstallMaintenance.Key(Path.GetTempPath().TrimEnd(Path.DirectorySeparatorChar),"SID-A"));Check(CodexLight.Shared.InstallMaintenance.Key(Path.GetTempPath(),"SID-A")!=CodexLight.Shared.InstallMaintenance.Key(Path.GetTempPath(),"SID-B"));var old=new[]{F("CodexLight.exe"),F("app/retired.js")};var receipt=new InstallReceipt(Guid.NewGuid().ToString("D"),@"C:\Users\USER\Apps\codexlight",old);var encoded=UpgradeReceiptCodec.Encode(receipt);Check(UpgradeReceiptCodec.Decode(encoded,receipt.Fingerprint(),receipt.Target).InstallId==receipt.InstallId);Reject(()=>UpgradeReceiptCodec.Decode(encoded,"bad",receipt.Target));Reject(()=>UpgradeReceiptCodec.Decode(encoded.Concat(new byte[]{32}).ToArray(),receipt.Fingerprint(),receipt.Target));var command="\""+receipt.Target+"\\Uninstall.exe\" /uninstall";
 Func<UpgradeFile[],UpgradeFile[],UpgradePlan> plan=(next,observed)=>UpgradePlanner.Create(receipt,receipt.Target,command,receipt.Fingerprint(),next,observed,false);
 var p=plan(new[]{F("CodexLight.exe","b"),F("app/new.js")},old.Concat(new[]{F(".codex/auth.json"),F("projects/own.txt")}).ToArray());Check(p.Steps.Count==3);Check(p.PreservedUnknown.Count==2);Check(p.Steps.Any(x=>x.Kind=="retire"));
 Reject(()=>plan(new[]{F("CodexLight.exe","b")},new[]{F("CodexLight.exe","c"),old[1]}));Reject(()=>plan(new[]{F("CodexLight.exe"),F("app/new.js")},old.Concat(new[]{F("app/new.js")}).ToArray()));Reject(()=>UpgradePlanner.Create(receipt,receipt.Target,command,"wrong",old,old,false));Reject(()=>UpgradePlanner.Create(receipt,receipt.Target,command,receipt.Fingerprint(),old,old,true));
 foreach(var path in new[]{"../x","C:/x","app/../x","a:stream","app/NUL.txt","app/x.","app/x ",".codex/auth.json","auth/token"})Reject(()=>UpgradePlanner.ValidateFiles(new[]{F(path)}));
 Reject(()=>UpgradePlanner.ValidateFiles(new[]{F("app/A"),F("app/a")}));Reject(()=>UpgradePlanner.ValidateFiles(new[]{F("app/a"),F("app/a/b")}));
 var j=new UpgradeJournal(p);Reject(()=>j.RegistrationCommitted());int first=j.Intent();j.Applied(first);int second=j.Intent();Check(j.BeginRollback().Count==2);Reject(()=>j.Applied(second));
 var complete=new UpgradeJournal(p);while(complete.Next()!=null){var n=complete.Intent();complete.Applied(n);}complete.FilesVerified();complete.RegistrationCommitted();Check(complete.Phase=="committed");Reject(()=>complete.BeginRollback());TransactionTests();OrchestratorTests();BoundedTests();Console.WriteLine($"{count} upgrade assertions passed; only temporary filesystem and mock registry used");}
}
